('miloszewskie-2027','Stanowisko 33','Zasilanie awaryjne / stacja powerbank',NULL,0,'1','AUTO:MIL33: brak potwierdzonego 230 V na stanowisku 33 — planować niezależne zasilanie',11),
('miloszewskie-2027','Stanowisko 33','Marker tyczkowy',NULL,0,'1–2','AUTO:MIL33: H-markery zabronione',12),
('miloszewskie-2027','Carp Care','Mata min. 70 × 120 cm z grubym materacem',NULL,0,'1','AUTO:MIL33: wymóg oficjalnego regulaminu',20),
('miloszewskie-2027','Carp Care','Duży podbierak karpiowy',NULL,0,'1+','AUTO:MIL33: wymóg oficjalnego regulaminu',21),
('miloszewskie-2027','Carp Care','Clinik / środek do dezynfekcji ran',NULL,0,'1','AUTO:MIL33: każda ryba po wyjęciu haka ma być zdezynfekowana',22),
('miloszewskie-2027','Łowienie','4 zestawy główne — 2 Patryk + 2 Maciek','Patryk + Maciek',0,'4','AUTO:MIL33: maksymalnie 2 wędki na osobę',30),
('miloszewskie-2027','Łowienie','Żyłka główna — bez plecionki',NULL,0,'4 kołowrotki','AUTO:MIL33: plecionka jako linka główna zabroniona',31),
('miloszewskie-2027','Łowienie','Zestawy denne na twarde przejścia / spad',NULL,0,'kilka','AUTO:MIL33: plan na 8,5–10,5 m po potwierdzeniu Deeperem',32),
('miloszewskie-2027','Łowienie','ZIG Rig — komplet do regulacji głębokości',NULL,0,'1 kpl.','AUTO:MIL33: udokumentowana metoda na stanowisku 33, plan B przy rybach w toni',33),
('miloszewskie-2027','Nęcenie','Gotowane konopie',NULL,0,'wg limitu','AUTO:MIL33: jedno z nielicznych dozwolonych ziaren; całkowity limit zanęty 3 kg/dobę',40),
('miloszewskie-2027','Nęcenie','Miękka kukurydza puszkowa',NULL,0,'wg limitu','AUTO:MIL33: dozwolony wyjątek w regulaminie',41),
('miloszewskie-2027','Nęcenie','NIE BRAĆ tygrysa do nęcenia',NULL,0,'0','AUTO:MIL33: orzech tygrysi jako ziarno do nęcenia jest zabroniony',42),
('miloszewskie-2027','Przyjazd','Zapisane numery: Karol 696 036 236 / Grzegorz 602 300 147',NULL,0,'1','AUTO:MIL33: rezerwacja i kontakt z gospodarzem',50),
('miloszewskie-2027','Przyjazd','Meldunek i opłata w rybaczówce — stanowisko 23',NULL,0,'1','AUTO:MIL33: wymagane przed rozpoczęciem łowienia',51),
('miloszewskie-2027','Przyjazd','Potwierdzić dojazd nr 2 do stanowiska 33',NULL,0,'1','AUTO:MIL33: przed wyjazdem potwierdzić stan drogi i możliwość dojazdu ciężkim autem',52),
('miloszewskie-2027','Przyjazd','Potwierdzić granice sektora 33 z sąsiadami / gospodarzem',NULL,0,'1','AUTO:MIL33: wywózka ma nie utrudniać łowienia z innych stanowisk',53);

